-- Brains Heist original Second Conditional assessment release v1.0.0
-- Owner commissioned on 2026-10-08. Content and taxonomy reviewed by AI.
-- 24 MCQs; Grades 7–10; six precise evidence focuses; A/B/C/D = 6 each.
-- Publication uses the existing service-only registry importer and existing constraints.
-- Run as the normal privileged content-import role, never from a browser client.
-- Idempotent on exact package content; content changes require a new version.
-- Verified in a rollback-only normal assignment test: Jess ESL search 24,
-- server scoring 12/24, 24 registry item evidence rows, six focus observations,
-- three strength / three focus observations, and teacher intervention intelligence.
-- Test data and attempts were rolled back. No student results are fabricated.
begin;
insert into public.academic_skill_evidence_focuses(registry_version_id,atomic_subskill_node_id,code,name,description,applicable_phases,source_method,source_fingerprint,status)
select rv.id,n.id,f->>'code',f->>'name',f->>'statement',n.applicable_phases,'platform_seed',encode(extensions.digest(f->>'statement','sha256'),'hex'),'active'
from public.academic_skill_registry_versions rv join public.academic_skill_registry_nodes n on n.registry_version_id=rv.id
cross join jsonb_array_elements('[{"key":"meaning","name":"Interpret imaginary or unlikely present and future situations expressed by the second conditional","ao":"BH-AO1","cog":"understand","code":"eng.use-of-english.conditionals.unreal.focus.second-conditional-meaning","statement":"A correct response shows that the learner can interpret imaginary or unlikely present and future situations expressed by the second conditional."},{"key":"if-clause","name":"Form the second-conditional if-clause using the past simple","ao":"BH-AO2","cog":"apply","code":"eng.use-of-english.conditionals.unreal.focus.second-conditional-if-clause","statement":"A correct response shows that the learner can form the second-conditional if-clause using the past simple."},{"key":"result-clause","name":"Form the second-conditional result clause using would plus a base verb","ao":"BH-AO2","cog":"apply","code":"eng.use-of-english.conditionals.unreal.focus.second-conditional-result-clause","statement":"A correct response shows that the learner can form the second-conditional result clause using would plus a base verb."},{"key":"negatives","name":"Form negative conditions and results in the second conditional","ao":"BH-AO2","cog":"apply","code":"eng.use-of-english.conditionals.unreal.focus.second-conditional-negatives","statement":"A correct response shows that the learner can form negative conditions and results in the second conditional."},{"key":"were-advice","name":"Use hypothetical were and If I were you to give advice in formal English","ao":"BH-AO2","cog":"apply","code":"eng.use-of-english.conditionals.unreal.focus.second-conditional-were-advice","statement":"A correct response shows that the learner can use hypothetical were and If I were you to give advice in formal English."},{"key":"real-unreal-contrast","name":"Distinguish likely future conditions from imaginary or unlikely conditions in context","ao":"BH-AO3","cog":"analyze","code":"eng.use-of-english.conditionals.unreal.focus.second-conditional-real-unreal-contrast","statement":"A correct response shows that the learner can distinguish likely future conditions from imaginary or unlikely conditions in context."}]'::jsonb) f
where rv.code='bh-english-core-v1' and rv.status='published' and n.code='eng.use-of-english.conditionals.unreal' and n.status='active'
on conflict(code) do nothing;
select public.rpc_import_registry_verified_mcq_package('{"schemaVersion":1,"packageId":"bh-english-second-conditional-v1","packageVersion":"1.0.0","contentVersion":"bh-english-second-conditional-v1.0.0","registryVersion":"bh-english-core-v1","subjectCode":"english","authority":"Brains Heist Content Quality · Owner-commissioned AI review","releaseNotes":"24 original MCQs; six precise evidence focuses; Grades 7–10; balanced A–D keys. Original classroom assessment content, not official Cambridge exam questions.","questions":[{"externalId":"bh-english-second-conditional-v1-q01","topic":"Second Conditional","questionType":"multiple_choice","questionText":"What does this sentence mean? ''If I owned a helicopter, I would fly to school.''","options":["The speaker owned a helicopter last year.","The speaker will definitely buy a helicopter.","The speaker is imagining owning a helicopter.","The speaker flies to school every day."],"correctAnswer":"The speaker is imagining owning a helicopter.","explanation":"The past form ''owned'' presents an imaginary situation now or in the future; it does not describe a past event.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","meaning"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-meaning","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"A correct response shows that the learner can interpret imaginary or unlikely present and future situations expressed by the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q02","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Read: ''If our town had a beach, we would swim there after school.'' What is the speaker doing?","options":["Imagining a different situation in the town.","Describing what the students did yesterday.","Promising that the town will build a beach.","Stating that the students already swim there daily."],"correctAnswer":"Imagining a different situation in the town.","explanation":"The second conditional imagines a town with a beach and the result of that imaginary condition.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","meaning"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-meaning","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"A correct response shows that the learner can interpret imaginary or unlikely present and future situations expressed by the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q03","topic":"Second Conditional","questionType":"multiple_choice","questionText":"In ''If Sami won the competition next month, he would celebrate with his friends'', why is ''won'' used?","options":["To prove that Sami won last month.","To say that Sami wins every competition.","To make winning a certain future event.","To present winning as an imagined or unlikely future condition."],"correctAnswer":"To present winning as an imagined or unlikely future condition.","explanation":"A past-simple form after ''if'' can refer to an imagined future, here explicitly ''next month''.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","meaning"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-meaning","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"A correct response shows that the learner can interpret imaginary or unlikely present and future situations expressed by the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q04","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Read: ''If I knew the answer, I would tell you.'' Which interpretation best fits the sentence?","options":["The speaker knows the answer but refuses to share it.","The speaker does not know the answer now.","The speaker told the answer yesterday.","The speaker is certain to learn the answer tomorrow."],"correctAnswer":"The speaker does not know the answer now.","explanation":"This unreal present condition implies that the speaker does not know the answer, so cannot tell it now.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","meaning"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-meaning","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"A correct response shows that the learner can interpret imaginary or unlikely present and future situations expressed by the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q05","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Choose the verb form for the second conditional: ''If Lina ___ more free time, she would join the drama club.''","options":["has","had","will have","would have"],"correctAnswer":"had","explanation":"Use past simple ''had'' in the if-clause; the result uses ''would join''.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","if-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-if-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional if-clause using the past simple."}]},{"externalId":"bh-english-second-conditional-v1-q06","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the second conditional: ''If my brother ___ closer to school, he would walk there.''","options":["lives","will live","would live","lived"],"correctAnswer":"lived","explanation":"The if-clause takes the past simple ''lived'' to express an imaginary present situation.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","if-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-if-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional if-clause using the past simple."}]},{"externalId":"bh-english-second-conditional-v1-q07","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the second conditional: ''If we ___ a new student tomorrow, we would show them around.''","options":["met","meet","will meet","would meet"],"correctAnswer":"met","explanation":"Use the past simple ''met'' after ''if''. Despite the past form, ''tomorrow'' makes this an imagined future.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","if-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-if-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional if-clause using the past simple."}]},{"externalId":"bh-english-second-conditional-v1-q08","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Which correction makes this a standard second conditional? ''If I would find a wallet, I would take it to the school office.''","options":["Change ''would take'' to ''will took''.","Change ''would find'' to ''will found''.","Change ''would find'' to ''found''.","Change ''would take'' to ''would taken''."],"correctAnswer":"Change ''would find'' to ''found''.","explanation":"The standard second-conditional condition uses ''if + past simple'': ''If I found a wallet, I would take it...''.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","if-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-if-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional if-clause using the past simple."}]},{"externalId":"bh-english-second-conditional-v1-q09","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the second conditional: ''If I had a bicycle, I ___ to the park.''","options":["will rode","would rode","would riding","would ride"],"correctAnswer":"would ride","explanation":"Use ''would + base verb'': ''would ride'', not a past or -ing form.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","result-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-result-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional result clause using would plus a base verb."}]},{"externalId":"bh-english-second-conditional-v1-q10","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the second conditional: ''If we had a larger classroom, we ___ more group activities.''","options":["would did","would do","will done","would doing"],"correctAnswer":"would do","explanation":"The result clause uses ''would do''. ''Do'' stays in its base form after ''would''.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","result-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-result-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional result clause using would plus a base verb."}]},{"externalId":"bh-english-second-conditional-v1-q11","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Choose the correctly formed second-conditional result: ''If Farida spoke Japanese, ___.''","options":["she would understood this conversation","she will understood this conversation","she would understand this conversation","she would understands this conversation"],"correctAnswer":"she would understand this conversation","explanation":"After ''would'', use the base form ''understand'', without -s and without changing it to the past.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","result-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-result-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional result clause using would plus a base verb."}]},{"externalId":"bh-english-second-conditional-v1-q12","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the second conditional with the result clause first: ''I ___ you with the project if I had enough time.''","options":["would help","would helped","will helping","would helps"],"correctAnswer":"would help","explanation":"The order of the clauses does not change the form: result ''would help'', condition ''if I had''.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","result-clause"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-result-clause","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form the second-conditional result clause using would plus a base verb."}]},{"externalId":"bh-english-second-conditional-v1-q13","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the negative second-conditional condition: ''If I ___ so far away, I would visit you more often.''","options":["didn''t live","don''t live","wouldn''t live","didn''t lived"],"correctAnswer":"didn''t live","explanation":"For a negative past-simple condition, use ''didn''t + base verb'': ''didn''t live''.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","negatives"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-negatives","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form negative conditions and results in the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q14","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the negative result: ''If we had a map, we ___ lost.''","options":["won''t got","wouldn''t got","wouldn''t get","don''t got"],"correctAnswer":"wouldn''t get","explanation":"A negative result uses ''wouldn''t + base verb'': ''wouldn''t get''.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","negatives"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-negatives","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form negative conditions and results in the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q15","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Complete the second conditional: ''If Aida ___ a phone, she would use the school computer to contact her parents.''","options":["doesn''t have","didn''t have","didn''t had","wouldn''t have"],"correctAnswer":"didn''t have","explanation":"The unreal negative condition uses ''didn''t have''. Do not use ''had'' after ''didn''t''.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","negatives"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-negatives","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form negative conditions and results in the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q16","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Which sentence is a correctly formed negative second conditional?","options":["If they would listen carefully, they didn''t miss the instructions.","If they listened carefully, they wouldn''t missed the instructions.","If they listens carefully, they wouldn''t miss the instructions.","If they listened carefully, they wouldn''t miss the instructions."],"correctAnswer":"If they listened carefully, they wouldn''t miss the instructions.","explanation":"Use past simple ''listened'' for the condition and ''wouldn''t + base verb miss'' for the result.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","negatives"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-negatives","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can form negative conditions and results in the second conditional."}]},{"externalId":"bh-english-second-conditional-v1-q17","topic":"Second Conditional","questionType":"multiple_choice","questionText":"In formal English, complete this imaginary condition: ''If I ___ the headteacher, I would start a reading club.''","options":["am","will be","were","would be"],"correctAnswer":"were","explanation":"Formal hypothetical English uses ''were'' with ''I'': ''If I were the headteacher...''.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","were-advice"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-were-advice","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can use hypothetical were and If I were you to give advice in formal English."}]},{"externalId":"bh-english-second-conditional-v1-q18","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Choose the standard expression for giving hypothetical advice: ''If I ___ you, I would ask the teacher for help.''","options":["am","will be","would be","were"],"correctAnswer":"were","explanation":"''If I were you'' is the standard hypothetical expression used to introduce advice.","difficulty":"easy","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","were-advice"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-were-advice","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can use hypothetical were and If I were you to give advice in formal English."}]},{"externalId":"bh-english-second-conditional-v1-q19","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Which sentence gives advice using a correctly formed second conditional?","options":["If I were you, I would check my answers before submitting.","If I am you, I would checked my answers before submitting.","If I would be you, I checked my answers before submitting.","If I were you, I would checking my answers before submitting."],"correctAnswer":"If I were you, I would check my answers before submitting.","explanation":"Advice uses ''If I were you'' followed by ''would + base verb'': ''would check''.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","were-advice"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-were-advice","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can use hypothetical were and If I were you to give advice in formal English."}]},{"externalId":"bh-english-second-conditional-v1-q20","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Your friend keeps forgetting homework. Which sentence gives hypothetical advice in formal English?","options":["If I am you, I will wrote the tasks in a planner.","If I were you, I would write the tasks in a planner.","If I would be you, I would wrote the tasks in a planner.","If I were you, I would writing the tasks in a planner."],"correctAnswer":"If I were you, I would write the tasks in a planner.","explanation":"The standard advice pattern is ''If I were you, I would...'' with the base verb ''write''.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","were-advice"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-were-advice","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"A correct response shows that the learner can use hypothetical were and If I were you to give advice in formal English."}]},{"externalId":"bh-english-second-conditional-v1-q21","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Sara has no ticket and thinks getting one is unlikely. Which sentence presents attending tomorrow''s concert as imaginary?","options":["If I get a ticket, I will go to the concert.","If I got a ticket, I would go to the concert.","When I get a ticket, I will go to the concert.","I got a ticket and went to the concert."],"correctAnswer":"If I got a ticket, I would go to the concert.","explanation":"The second conditional ''got...would go'' presents getting a ticket as imaginary or unlikely; the first conditional treats it as a real future possibility.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","real-unreal-contrast"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-real-unreal-contrast","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"A correct response shows that the learner can distinguish likely future conditions from imaginary or unlikely conditions in context."}]},{"externalId":"bh-english-second-conditional-v1-q22","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Compare: A: ''If I save enough money, I will buy a laptop.'' B: ''If I had a million dollars, I would buy a recording studio.'' Which interpretation is correct?","options":["A presents a real future possibility; B presents an imaginary situation.","A describes a completed past event; B describes a daily habit.","A presents an impossible past; B promises a certain future.","Both sentences say the speakers have already made their purchases."],"correctAnswer":"A presents a real future possibility; B presents an imaginary situation.","explanation":"Present simple + will expresses a real future possibility. Past simple + would expresses an imaginary present or future situation.","difficulty":"hard","points":1,"timeLimit":60,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","real-unreal-contrast"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-real-unreal-contrast","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"A correct response shows that the learner can distinguish likely future conditions from imaginary or unlikely conditions in context."}]},{"externalId":"bh-english-second-conditional-v1-q23","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Omar is preparing for an exam and thinks passing is a realistic possibility. Which sentence best expresses that real future possibility?","options":["If I passed the exam, I would celebrate.","If I had passed the exam, I would have celebrated.","If I would pass the exam, I celebrate.","If I pass the exam, I will celebrate."],"correctAnswer":"If I pass the exam, I will celebrate.","explanation":"For a realistic future possibility, use the first conditional: ''if + present simple'' and ''will + base verb''. The second conditional would make it hypothetical.","difficulty":"medium","points":1,"timeLimit":45,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","real-unreal-contrast"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-real-unreal-contrast","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"A correct response shows that the learner can distinguish likely future conditions from imaginary or unlikely conditions in context."}]},{"externalId":"bh-english-second-conditional-v1-q24","topic":"Second Conditional","questionType":"multiple_choice","questionText":"Read: ''If our school had a swimming pool, we would practise there.'' Which sentence changes this imaginary situation into a real future possibility?","options":["If our school got a swimming pool, we would practise there.","If our school had got a swimming pool, we would have practised there.","If our school gets a swimming pool, we will practise there.","If our school would get a swimming pool, we practised there."],"correctAnswer":"If our school gets a swimming pool, we will practise there.","explanation":"Changing to ''if + present simple gets'' and ''will practise'' presents getting a pool as a real future possibility.","difficulty":"hard","points":1,"timeLimit":60,"eligibleGrades":[7,8,9,10],"language":"en","tags":["second conditional","hypothetical meaning","real-unreal-contrast"],"taxonomies":[{"primarySkillCode":"eng.use-of-english.conditionals","atomicSubskillCode":"eng.use-of-english.conditionals.unreal","evidenceFocusCode":"eng.use-of-english.conditionals.unreal.focus.second-conditional-real-unreal-contrast","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"A correct response shows that the learner can distinguish likely future conditions from imaginary or unlikely conditions in context."}]}]}'::jsonb,false);
set constraints all immediate;
commit;
